def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str) or not name.isidentifier():
        raise ValueError(f"Name must be a valid identifier: {name!r}")
    if not isinstance(fields, (list, tuple)):
        raise ValueError(f"Fields must be a list or tuple: {fields!r}")
    if not isinstance(srid_map, dict):
        raise ValueError(f"SRID map must be a dictionary: {srid_map!r}")

    class Point:
        __slots__ = fields

        def __init__(self, *args, **kwargs):
            if len(args) > len(fields):
                raise TypeError(f"Expected {len(fields)} arguments, got {len(args)}")
            for i, value in enumerate(args):
                setattr(self, fields[i], value)
            for key, value in kwargs.items():
                if key not in fields:
                    raise TypeError(f"Unexpected keyword argument: {key!r}")
                setattr(self, key, value)
            for field in fields:
                if not hasattr(self, field):
                    raise TypeError(f"Missing value for field: {field!r}")

        def __repr__(self):
            field_values = ', '.join(f"{field}={getattr(self, field)!r}" for field in fields)
            return f"{name}({field_values})"

    return type(name, (Point,), {})

