def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")

    if self.SQLParams.in_style in ['named', 'pyformat', 'format']:
        if not isinstance(params, (dict, Mapping)):
            raise TypeError("params must be a dict for named parameter style")
    elif self.SQLParams.in_style in ['qmark', 'numeric', 'ordinal']:
        if not isinstance(params, (list, Sequence)):
            raise TypeError("params must be a list for ordinal parameter style")
    else:
        raise ValueError("Unsupported SQL parameter style")

    if self.SQLParams.out_style == self.SQLParams.in_style:
        return sql, params

    if self.SQLParams.in_style == 'named':
        if self.SQLParams.out_style == 'qmark':
            placeholders = '?' * len(params)
            converted_sql = re.sub(r':([a-zA-Z_][a-zA-Z0-9_]*)', '?', sql)
            return converted_sql, list(params.values())
        elif self.SQLParams.out_style == 'numeric':
            placeholders = ''.join(f':{i+1}' for i in range(len(params)))
            converted_sql = re.sub(r':([a-zA-Z_][a-zA-Z0-9_]*)', lambda m: f':{list(params.keys()).index(m.group(1)) + 1}', sql)
            return converted_sql, list(params.values())
    elif self.SQLParams.in_style == 'qmark':
        if self.SQLParams.out_style == 'named':
            placeholders = ','.join(f':{param}' for param in params)
            converted_sql = re.sub(r'\?', lambda m, i=iter(params): f':{next(i)}', sql)
            return converted_sql, dict(zip(params, params))
    elif self.SQLParams.in_style == 'numeric':
        if self.SQLParams.out_style == 'named':
            named_params = {f'p{i}': params[i] for i in range(len(params))}
            placeholders = ','.join(f':p{i}' for i in range(len(params)))
            converted_sql = re.sub(r':(\d+)', lambda m: f':p{int(m.group(1))}', sql)
            return converted_sql, named_params

    raise ValueError("Conversion between parameter styles is not implemented")

