            converted_sql = re.sub(r'\?', lambda m, i=iter(params): f':{next(i)}', sql)
            return converted_sql, dict(zip(params, params))
    elif self.SQLParams.in_style == 'numeric':
        if self.SQLParams.out_style == 'named':
