    for digest in digests_used:
        if not isinstance(digest, str):
            raise ValueError("Each item in digests_used must be a string.")
        if digest not in digests_in_manifest:
            return False  # A digest used is not present in the manifest

    return all(digest in digests_used for digest in digests_in_manifest)  # All digests in manifest are used

