def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not inventory:
        raise ValueError("Inventory cannot be empty.")

    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory.")

    logical_path_map = {}

    for logical_path, file_info in inventory[version].items():
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(file_info['content_file'])

    # Include references to duplicate files from later versions
    all_versions = sorted(inventory.keys(), key=lambda v: inventory[v]['timestamp'])
    current_index = all_versions.index(version)

    for later_version in all_versions[current_index + 1:]:
        if later_version in inventory:
            for logical_path, file_info in inventory[later_version].items():
                if logical_path in logical_path_map:
                    logical_path_map[logical_path].add(file_info['content_file'])

    return logical_path_map

