def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string")

    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            xml_data = {}
            for zinfo in zin.infolist():
                if zinfo.filename.endswith('.xml'):
                    base_name = os.path.basename(zinfo.filename)
                    if base_name not in xml_data:
                        xml_data[base_name] = []
                    xml_data[base_name].append(zin.read(zinfo.filename))
            return xml_data
    except zipfile.BadZipFile:
        raise ValueError("Invalid ZIP file")
    except FileNotFoundError:
        raise FileNotFoundError("The specified ZIP file does not exist")
    except Exception as e:
        raise Exception(f"An error occurred: {str(e)}")

