def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    result = []

    def format_value(value, indent_level):
        if isinstance(value, dict):
            items = []
            for key, val in value.items():
                items.append(f"{indent_str * (indent_level + 1)}{key}: {format_value(val, indent_level + 1)}")
            return "{\n" + ",\n".join(items) + f"\n{indent_str * indent_level}}"
        elif isinstance(value, list):
            items = []
            for item in value:
                items.append(f"{indent_str * (indent_level + 1)}- {format_value(item, indent_level + 1)}")
            return "[\n" + ",\n".join(items) + f"\n{indent_str * indent_level}]"
        elif isinstance(value, str):
            return f"'{value}'"
        else:
            return str(value)

    for key, value in self.__dict__.items():
        if not debug and key.startswith('_'):
            continue
        result.append(f"{indent_str}{key}: {format_value(value, 1)}")

    return ",\n".join(result)

