def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if len(expr) != 3:
            return expr
        op, a, b = expr
        if op == '&':
            if b[0] == '|' and b[1] == a:
                return a
            if b[0] == '|' and b[2] == a:
                return a
            if b[0] == '|' and b[1][0] == '~' and b[1][1] == a:
                return ('&', a, b[2])
            if b[0] == '|' and b[2][0] == '~' and b[2][1] == a:
                return ('&', a, b[1])
        if op == '|':
            if b[0] == '&' and b[1] == a:
                return a
            if b[0] == '&' and b[2] == a:
                return a
            if b[0] == '&' and b[1][0] == '~' and b[1][1] == a:
                return ('|', a, b[2])
            if b[0] == '&' and b[2][0] == '~' and b[2][1] == a:
                return ('|', a, b[1])
        return expr

    new_args = []
    for expr in args:
        new_expr = apply_absorption(expr)
        if new_expr != expr:
            new_expr = apply_absorption(new_expr)  # Apply absorption again in case of nested expressions
        new_args.append(new_expr)
    return new_args

