def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list) or not all(isinstance(v, str) for v in version_dirs):
        raise ValueError("version_dirs must be a list of strings representing version directory names.")

    root_inventory = {}
    divergent_digests = {}

    try:
        # Load root inventory assuming it's in the first version directory
        with open(f"{version_dirs[0]}/inventory.json", 'r') as f:
            root_inventory = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Failed to load root inventory from {version_dirs[0]}/inventory.json: {e}")

    for version_dir in version_dirs:
        version_inventory_path = f"{version_dir}/inventory.json"
        try:
            with open(version_inventory_path, 'r') as f:
                version_inventory = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError) as e:
            raise ValueError(f"Failed to load inventory from {version_inventory_path}: {e}")

        # Check for missing items in the version inventory compared to root
        for key, root_digest in root_inventory.items():
            if key not in version_inventory:
                raise ValueError(f"Missing inventory item {key} in version {version_dir}.")

        # Record divergent digests
        for key, version_digest in version_inventory.items():
            if root_inventory.get(key) != version_digest:
                if key not in divergent_digests:
                    divergent_digests[key] = set()
                divergent_digests[key].add(version_digest)

    # Check for any divergent digests
    for key, digests in divergent_digests.items():
        if len(digests) > 1:
            raise ValueError(f"Content digest for {key} differs across versions: {digests}")

