def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(c, str) for c in commands):
        raise ValueError("Commands must be a list of strings.")
    if not isinstance(args, list) or not all(isinstance(a, str) for a in args):
        raise ValueError("Args must be a list of strings.")

    full_command = commands + args

    try:
        stdout = subprocess.PIPE if verbose else subprocess.DEVNULL
        stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        process = subprocess.run(full_command, cwd=cwd, env=env, stdout=stdout, stderr=stderr, text=True, check=False)

        if verbose:
            print(process.stdout)

        if process.returncode != 0:
            error_message = process.stderr if process.stderr else "Command failed with return code " + str(process.returncode)
            raise subprocess.CalledProcessError(process.returncode, full_command, output=process.stdout, stderr=error_message)

    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(e.returncode, e.cmd, output=e.output, stderr=e.stderr)
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

