def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import json
    import logging.config

    if overrides is None:
        overrides = {}

    configurations = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config_data = json.load(file)
                configurations[filename] = config_data
        except FileNotFoundError:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"File not found: {filename}", args=(), exc_info=True))
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"JSON decode error in {filename}: {e}", args=(), exc_info=True))

    # Apply overrides
    for key, value in overrides.items():
        for config in configurations.values():
            config[key] = value

    # Resolve environment variables if required
    if resolve_env:
        import re
        env_var_pattern = re.compile(r'\$\{([^}]+)\}')
        for filename, config in configurations.items():
            try:
                configurations[filename] = _resolve_env_vars(config, env_var_pattern)
            except Exception as e:
                log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error resolving environment variables in {filename}: {e}", args=(), exc_info=True))

    return configurations, log_records

def _resolve_env_vars(config, pattern):
    if isinstance(config, dict):
        return {k: _resolve_env_vars(v, pattern) for k, v in config.items()}
    elif isinstance(config, list):
        return [_resolve_env_vars(v, pattern) for v in config]
    elif isinstance(config, str):
        return pattern.sub(lambda m: os.getenv(m.group(1), m.group(0)), config)
    else:
        return config

