def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET
    from xml.parsers.expat import ExpatError

    try:
        # Try to parse as JSON
        data = json.loads(document)
        if 'links' in data and isinstance(data['links'], list):
            hcard_url = next((link['href'] for link in data['links'] if link.get('rel') == 'http://microformats.org/profile/hcard'), None)
            return {'hcard_url': hcard_url} if hcard_url else {}
        else:
            logger.warning("parse_diaspora_webfinger: JSON format is incorrect")
            return {}
    except json.JSONDecodeError:
        # Try to parse as XRD
        try:
            root = ET.fromstring(document)
            if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                logger.warning("parse_diaspora_webfinger: XRD format is incorrect")
                return {}
            hcard_url = root.find('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link[@rel="http://microformats.org/profile/hcard"]')
            return {'hcard_url': hcard_url.attrib.get('href')} if hcard_url is not None else {}
        except (ET.ParseError, ExpatError):
            logger.warning("parse_diaspora_webfinger: Failed to parse document as XRD")
            return {}
    except Exception as e:
        logger.error("parse_diaspora_webfinger: Unexpected error: %s", e)
        return {}

