def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    try:
        parser = self.parsers[parser_name]
    except KeyError:
        raise ValueError(f"No parser found for command: {parser_name}")

    for arg, value in values_dict.items():
        try:
            action = [act for act in parser._actions if act.dest == arg][0]
        except IndexError:
            continue  # If the argument is not found in parser, skip it

        try:
            if isinstance(action.type, type):
                values_dict[arg] = action.type(value)
            elif callable(action.type):
                values_dict[arg] = action.type(value)
        except (ValueError, TypeError) as e:
            raise ValueError(f"Error converting argument '{arg}': {e}")

